#include "../Source/PluginEditor.h"
#include <iostream>
#include <stdexcept>
namespace {
void need(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
void set(SpaceInfinityProcessor& p,const juce::String& id,float value){auto* a=p.state.getParameter(id);need(a!=nullptr,id.toRawUTF8());a->setValueNotifyingHost(a->convertTo0to1(value));}
float get(SpaceInfinityProcessor& p,const juce::String& id){return p.state.getRawParameterValue(id)->load();}
juce::Component* find(juce::Component& c,const juce::String& name){if(c.getName()==name)return &c;for(auto* child:c.getChildren())if(auto* f=find(*child,name))return f;return nullptr;}
void page(juce::Component& editor,const char* name){for(auto* c:editor.getChildren())if(auto* b=dynamic_cast<juce::TextButton*>(c))if(b->getButtonText()==name){b->onClick();return;}throw std::runtime_error("missing page");}
juce::MouseEvent event(juce::Component& c,juce::Point<float> position,juce::Point<float> start,int flags=0,bool dragged=false){return {juce::Desktop::getInstance().getMainMouseSource(),position,juce::ModifierKeys(flags),1,0,0,0,0,&c,&c,juce::Time::getCurrentTime(),start,juce::Time::getCurrentTime(),1,dragged};}
void clean(SpaceInfinityProcessor& p,bool protection){p.loadPreset(0);for(auto id:{"compEnabled","delayEnabled","reverbEnabled","chorusEnabled","flangerEnabled","phaserEnabled","gateEnabled","pumpEnabled","eqEnabled","convolverEnabled","osc2Enabled"})set(p,id,0);set(p,"declickEnabled",protection?1:0);set(p,"osc1PhaseReset",1);set(p,"wave",2);set(p,"mix",0);set(p,"gain",.5f);set(p,"routeA",0);set(p,"ampSustain",1);set(p,"attack",0);set(p,"release",0);set(p,"drive",0);set(p,"noiseLevel",0);}
std::vector<float> capture(bool protection,const juce::File* sample,int action){auto p=std::make_unique<SpaceInfinityProcessor>();clean(*p,protection);if(sample){need(p->importSample(*sample).wasOk(),"sample fixture import");set(*p,"source",3);set(*p,"sampleRoot",60);set(*p,"sampleLoop",0);}if(action==2){set(*p,"osc1Enabled",0);set(*p,"subLevel",1);}p->prepareToPlay(48000,64);juce::AudioBuffer<float> audio(2,64);std::vector<float> result;for(int b=0;b<64;++b){if(b==20&&action==1)set(*p,"osc1Gain",-60);if(b==20&&action==2)set(*p,"subEnabled",0);juce::MidiBuffer midi;if(b==0)midi.addEvent(juce::MidiMessage::noteOn(1,sample?60:32,1.0f),0);p->processBlock(audio,midi);for(int i=0;i<64;++i){const float v=audio.getSample(0,i);need(std::isfinite(v),"click-test finite audio");result.push_back(v);}}return result;}
double jump(const std::vector<float>& values,int start,int end){double largest=0;for(int i=start;i<end;++i)largest=std::max(largest,double(std::abs(values[size_t(i)]-values[size_t(i-1)])));return largest;}
}
int runRhythmWorkflowSmoke(){try{
    studio::Rhythm::Settings s;s.gate=true;s.curveMode=true;s.depth=1;s.smooth=.1f;s.curve.count=2;s.curve.x[0]=0;s.curve.x[1]=1;s.curve.y[0]=0;s.curve.y[1]=1;
    studio::Rhythm fx;fx.prepare(48000);fx.configure(s,120);fx.setBeat(.25);fx.process(1,1,0);need(std::abs(fx.displayPhase-.25)<.001,"curve rate / beat position");
    s.phase=.25f;fx.configure(s,120);fx.setBeat(0);fx.process(1,1,0);need(std::abs(fx.displayPhase-.25)<.001,"gate phase offset");
    s.phase=0;s.pwm=.25f;fx.configure(s,120);fx.setBeat(.25);fx.process(1,1,0);need(std::abs(fx.displayPhase-.5)<.001,"gate PWM mapping");
    s.pwm=.5f;s.swing=.5f;fx.configure(s,120);fx.setBeat(.5);fx.process(1,1,0);need(std::abs(fx.displayPhase-1.0f/3)<.001,"gate swing mapping");
    s.swing=0;s.retrigger=true;fx.configure(s,120);fx.setBeat(.8);fx.midi(juce::MidiMessage::noteOn(1,60,1.0f));fx.process(1,1,0);need(fx.displayPhase<.001,"MIDI curve retrigger");
    s.noteGate=true;s.curve.y[0]=s.curve.y[1]=1;fx.prepare(48000);fx.configure(s,120);for(int i=0;i<1000;++i)fx.process(1,1,0);need(fx.gateGain<.00001,"note gate closed without MIDI");fx.midi(juce::MidiMessage::noteOn(1,60,1.0f));for(int i=0;i<1000;++i)fx.process(1,1,0);need(fx.gateGain>.999,"note gate opens");fx.midi(juce::MidiMessage::noteOff(1,60));for(int i=0;i<1000;++i)fx.process(1,1,0);need(fx.gateGain<.00001,"note gate releases");
    const auto splitEnergy=[](float hz){studio::Rhythm f;f.prepare(48000);auto settings=studio::Rhythm::Settings{};settings.gate=true;settings.curveMode=true;settings.curve.count=2;settings.curve.x[1]=1;settings.curve.y[0]=settings.curve.y[1]=0;settings.split=1;settings.smooth=.1f;f.configure(settings,120);double energy=0;for(int i=0;i<32000;++i){const float value=.2f*std::sin(juce::MathConstants<float>::twoPi*hz*i/48000);auto out=f.process(value,value,0);if(i>16000)energy+=out[0]*out[0];}return energy;};need(splitEnergy(50)<10&&splitEnergy(5000)>250,"curve gating only the bass band");
    auto p=std::make_unique<SpaceInfinityProcessor>();
    for(int rate=0;rate<7;++rate)for(int preset=0;preset<15;++preset){set(*p,"gateRate",float(rate));p->loadGatePreset(preset);p->useGateCurveFromSteps();need(int(get(*p,"gateCurveRate"))==rate+4,"preserve legacy pattern duration");studio::EditableCurve c;c.count=int(get(*p,"gateCurveCount"));for(int i=0;i<c.count;++i){c.x[size_t(i)]=get(*p,"gateCurveX"+juce::String(i));c.y[size_t(i)]=get(*p,"gateCurveY"+juce::String(i));c.bend[size_t(i)]=get(*p,"gateCurveBend"+juce::String(i));}for(int step=0;step<16;++step)need(std::abs(c.value((step+.5f)/16)-studio::gatePatterns[size_t(preset)][size_t(step)])<.0001,"all fifteen curve presets retain steps");}
    for(int i=0;i<16;++i)set(*p,"gateStep"+juce::String(i),1);p->useGateCurveFromSteps();need(get(*p,"gateCurveCount")==2,"constant gate simplifies to two editable points");
    set(*p,"gateMode",1);set(*p,"gateCurveCount",2);set(*p,"gateCurveX0",0);set(*p,"gateCurveX1",1);set(*p,"gateCurveY0",.2f);set(*p,"gateCurveY1",.8f);
    auto editor=std::unique_ptr<juce::AudioProcessorEditor>(p->createEditor());editor->setSize(800,760);page(*editor,"GATE");auto* gate=find(*editor,"Dedicated audio gate and sidechain page");auto* seq=find(*editor,"Dedicated note sequencer page");need(gate&&gate->isVisible()&&seq&&!seq->isVisible(),"gate and sequencer separated");auto* graph=dynamic_cast<CurveEditor*>(find(*editor,"Audio gate curve"));need(graph!=nullptr,"gate graph visible");auto area=graph->getLocalBounds().toFloat().reduced(9);auto point=juce::Point<float>(area.getX()+area.getWidth()*.4f,area.getY()+area.getHeight()*.2f);graph->mouseDoubleClick(event(*graph,point,point));need(int(get(*p,"gateCurveCount"))==3,"add free gate point");juce::MouseWheelDetails wheel;wheel.deltaY=.5f;auto bend=juce::Point<float>(area.getX()+area.getWidth()*.2f,area.getCentreY());graph->mouseWheelMove(event(*graph,bend,bend),wheel);need(get(*p,"gateCurveBend0")>.1f,"bend segment with mouse wheel");graph->setSnap(16);graph->setSnapEnabled(true);graph->mouseDown(event(*graph,point,point));auto moved=juce::Point<float>(area.getX()+area.getWidth()*.49f,area.getY()+area.getHeight()*.31f);graph->mouseDrag(event(*graph,moved,point,juce::ModifierKeys::leftButtonModifier,true));graph->mouseUp(event(*graph,moved,point));need(std::abs(get(*p,"gateCurveX1")-.5f)<.0001&&std::abs(get(*p,"gateCurveY1")-.6875f)<.0001,"snap free point to grid");auto actual=juce::Point<float>(area.getCentreX(),area.getBottom()-area.getHeight()*.6875f);graph->mouseDoubleClick(event(*graph,actual,actual));need(int(get(*p,"gateCurveCount"))==2,"remove free gate point");
    page(*editor,"SEQ");need(seq->isVisible()&&!gate->isVisible(),"sequence page independent from audio gate");const float gateBefore=get(*p,"gateDepth");auto* pitch=dynamic_cast<ModSlider*>(find(*editor,"Sequence pitch 1"));need(pitch!=nullptr,"editable sequence pitch");pitch->setValue(7,juce::sendNotificationSync);need(get(*p,"stepPitch0")==7&&get(*p,"gateDepth")==gateBefore,"note editing does not edit gate");
    need(p->dropModulation("INFINITY:LFO:0","stepVelocity0"),"LFO to sequence accents");need(p->dropModulation("INFINITY:LFO:0","gatePhase"),"LFO to gate phase");need(p->dropModulation("INFINITY:LFO:0","irOutput"),"LFO to convolution output");need(p->flexibleTargetIndex("irSize")<0,"offline impulse transform not falsely offered for live modulation");
    auto* velocity=dynamic_cast<ModSlider*>(find(*editor,"Sequence velocity 1"));need(velocity!=nullptr,"sequence accent drop target");const float unchanged=get(*p,"stepVelocity0");const auto depth=p->modulationDepthFor("INFINITY:LFO:0","stepVelocity0");set(*p,depth,-.2f);velocity->mouseWheelMove(event(*velocity,{5,5},{5,5},juce::ModifierKeys::altModifier),wheel);need(get(*p,depth)>-.2f&&get(*p,"stepVelocity0")==unchanged,"target-side amount editing leaves base value unchanged");
    juce::MemoryBlock state;p->getStateInformation(state);auto recalled=std::make_unique<SpaceInfinityProcessor>();recalled->setStateInformation(state.getData(),int(state.getSize()));for(const auto* id:{"gateCurveCount","gateCurveX1","gateCurveBend0","gatePhase","gatePWM","stepPitch0"})need(get(*p,id)==get(*recalled,id),"gate/sequencer state recall");need(recalled->flexibleSourceTarget(3,0)==p->flexibleSourceTarget(3,0),"cross-page modulation recall");editor.reset();
    const auto folder=juce::File::getSpecialLocation(juce::File::tempDirectory).getNonexistentChildFile("InfinityClicks",{},false);folder.createDirectory();const auto sample=folder.getChildFile("abrupt-end.wav");juce::AudioBuffer<float> constant(1,1200);for(int i=0;i<1200;++i)constant.setSample(0,i,.7f);{auto out=sample.createOutputStream();juce::WavAudioFormat wav;std::unique_ptr<juce::AudioFormatWriter> writer(wav.createWriterFor(out.get(),48000,1,24,{},0));need(writer!=nullptr,"click fixture writer");out.release();need(writer->writeFromAudioSampleBuffer(constant,0,1200),"click fixture data");}
    for(int action=0;action<3;++action){const auto before=capture(false,action==0?&sample:nullptr,action),after=capture(true,action==0?&sample:nullptr,action);const int edge=action==0?1199:1280;const auto oldJump=jump(before,edge-12,edge+220),newJump=jump(after,edge-12,edge+220);std::cout<<"De-click "<<action<<" max delta "<<oldJump<<" -> "<<newJump<<'\n';need(newJump<oldJump*.5,"sample end / live oscillator gain / sub switch click reduction");}
    folder.deleteRecursively();std::cout<<"Rhythm workflow: curve editing/timing, fifteen presets, MIDI, bass-only gating, separate sequencer, modulation amounts, recall and measured click reduction passed\n";return 0;
}catch(const std::exception& e){std::cerr<<"Rhythm workflow failure: "<<e.what()<<'\n';return 121;}}
